), inserted AS (
  INSERT INTO troubleshooting_step (
    case_id, step_number, tier, check_measurement, step_reference,
    diagnostic_question, required_instrument, expected_observation, interpretation,
    possible_failure_indication, next_step, safety_warning,
    supervisor_approval_required
  )
  SELECT
    c.case_id, s.step_number, s.tier, s.check_measurement, s.step_reference,
    s.diagnostic_question, s.required_instrument, s.expected_observation, s.interpretation,
    s.possible_failure_indication, s.next_step, s.safety_warning,
    s.supervisor_approval_required
  FROM source_rows s
  JOIN operational_case c
    ON c.case_reference = s.case_reference
   AND c.organization_id = 'b2a7dce7-b449-4381-ba3b-b520f2c88c2e'
  ON CONFLICT (case_id, step_number) DO NOTHING
  RETURNING 1
)
SELECT
  (SELECT COUNT(*) FROM source_rows) AS source_rows,
  (SELECT COUNT(DISTINCT case_reference) FROM source_rows) AS source_cases,
  (SELECT COUNT(*) FROM inserted) AS newly_inserted,
  (SELECT COUNT(*) FROM troubleshooting_step ts
     JOIN operational_case c ON c.case_id = ts.case_id
    WHERE c.organization_id = 'b2a7dce7-b449-4381-ba3b-b520f2c88c2e') AS total_steps_for_organization,
  (SELECT COUNT(*) FROM source_rows s
     LEFT JOIN operational_case c
       ON c.case_reference = s.case_reference
      AND c.organization_id = 'b2a7dce7-b449-4381-ba3b-b520f2c88c2e'
    WHERE c.case_id IS NULL) AS unmatched_case_references;

-- Verify that Tier 3 rows require supervisor approval and there are no duplicate step numbers.
SELECT ts.tier, ts.supervisor_approval_required, COUNT(*) AS step_count
FROM troubleshooting_step ts
JOIN operational_case c ON c.case_id = ts.case_id
WHERE c.organization_id = 'b2a7dce7-b449-4381-ba3b-b520f2c88c2e'
GROUP BY ts.tier, ts.supervisor_approval_required
ORDER BY ts.tier, ts.supervisor_approval_required;

COMMIT;
